import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Definition Editor","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/skills/editor.md","filePath":"en/modules/skills/editor.md","lastUpdated":0}`),a={name:`en/modules/skills/editor.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="definition-editor" tabindex="-1">Definition Editor <a class="header-anchor" href="#definition-editor" aria-label="Permalink to “Definition Editor”">​</a></h1><p>This page covers the EmakiSkills in-game definition editor: how to open it, how the browser and editor GUIs work, which definitions you can edit, how edits are validated and saved, and the edit-backups mechanism</p><p>The editor is for server owners and config editors: browse, create, modify, and delete definition files under <code>skills/</code> and <code>resources/</code> without leaving the game. What each skill or resource field means still belongs to <a href="./definitions.html">Skill definitions</a>; this page only covers the editor itself</p><h2 id="opening-the-editor" tabindex="-1">Opening the editor <a class="header-anchor" href="#opening-the-editor" aria-label="Permalink to “Opening the editor”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>/eskills edit</code></td><td>Open the definition browser, listing every category and definition file</td></tr><tr><td><code>/eskills edit &lt;id&gt;</code></td><td>Open the editor page of that definition directly; ids tab-complete across skills and local resources</td></tr></tbody></table><p>The permission is <code>emakiskills.edit</code> or <code>emakiskills.admin</code> (default op), and the command is <strong>players only</strong>: running it from the console replies with a player-only notice. An unknown id replies &quot;Could not open the editor for %id%&quot;</p><h2 id="what-you-can-edit" tabindex="-1">What you can edit <a class="header-anchor" href="#what-you-can-edit" aria-label="Permalink to “What you can edit”">​</a></h2><p>The browser groups definitions by category; each category maps to a directory:</p><table tabindex="0"><thead><tr><th>Category</th><th>Location</th><th>New-file skeleton</th></tr></thead><tbody><tr><td>Skill definitions</td><td><code>skills/*.yml</code></td><td><code>id</code>, <code>display_name</code>, <code>description</code>, <code>icon_material</code>, <code>trigger_type</code>, <code>cooldown_ticks</code>, <code>global_cooldown_ticks</code>, <code>tags</code>, <code>tab_tags</code>, <code>conflicting_skills</code>, <code>required_skills</code>, <code>show_in_slots</code>, <code>ui_category</code>, <code>sort_order</code>, <code>enabled</code>, <code>resource_costs</code>, <code>variables</code>, <code>script</code>, <code>upgrade</code></td></tr><tr><td>Local resources</td><td><code>resources/*.yml</code></td><td><code>id</code>, <code>display_name</code>, <code>max</code>, <code>default_current</code>, <code>regen_amount</code>, <code>regen_interval_ticks</code>, <code>clamp_min</code>, <code>clamp_max</code></td></tr></tbody></table><ul><li>A file&#39;s id comes from the <code>id</code> key inside it, falling back to the file name without the extension.</li><li>New definitions are prefilled from the skeleton above; the skill skeleton starts with an empty <code>script</code> action pipeline in <code>mode: native</code> and a disabled <code>upgrade</code> block with <code>max_level: 1</code>. Edit the fields from there.</li><li>The bundled example skills (<code>example_*.yml</code>) and the example script skill are ordinary definition files too: browse, edit, or delete them like any other</li></ul><h2 id="definition-browser-editor-browser-gui-yml" tabindex="-1">Definition browser (editor_browser_gui.yml) <a class="header-anchor" href="#definition-browser-editor-browser-gui-yml" aria-label="Permalink to “Definition browser (editor_browser_gui.yml)”">​</a></h2><p><code>/eskills edit</code> with no argument opens the browser: definition files across categories, one screen per page. The template is <code>gui/editor_browser_gui.yml</code>, a 5-row layout (row 1 back/close, rows 2-4 content, row 5 paging and create):</p><table tabindex="0"><thead><tr><th>Slot key</th><th>Type</th><th>Default position</th><th>Meaning</th></tr></thead><tbody><tr><td><code>doc_entry</code></td><td><code>field_entry</code></td><td>content rows 2-4</td><td>Definition entry; left-click opens the editor page, right-click deletes (double confirmation, auto-backup first)</td></tr><tr><td><code>back</code></td><td><code>back</code></td><td>0</td><td>Back / close the browser</td></tr><tr><td><code>close</code></td><td><code>close</code></td><td>8</td><td>Close the browser</td></tr><tr><td><code>page_prev</code></td><td><code>page_prev</code></td><td>36</td><td>Previous page</td></tr><tr><td><code>page_info</code></td><td><code>page_info</code></td><td>38</td><td>Page number and definition count (<code>%current_page%</code>, <code>%total_pages%</code>, <code>%menu_title%</code>, <code>%entry_count%</code>)</td></tr><tr><td><code>page_next</code></td><td><code>page_next</code></td><td>40</td><td>Next page</td></tr><tr><td><code>new_doc</code></td><td><code>new_doc</code></td><td>42</td><td>Create a definition: pick a category, then type the new id in chat</td></tr><tr><td><code>border</code></td><td><code>filler</code></td><td>remaining slots</td><td>Decorative filler, not interactive</td></tr></tbody></table><p>Creation rules: ids may only contain lowercase letters, digits, and underscores (e.g. <code>my_skill</code>); an illegal id, a duplicate id, or a category that does not support creation is rejected with a message (both categories support create and delete). Deleting takes two clicks: the first &quot;Delete&quot; opens the confirmation screen, &quot;Confirm delete&quot; executes, and &quot;Cancel&quot; leaves everything untouched</p><h2 id="editor-page-editor-page-gui-yml" tabindex="-1">Editor page (editor_page_gui.yml) <a class="header-anchor" href="#editor-page-editor-page-gui-yml" aria-label="Permalink to “Editor page (editor_page_gui.yml)”">​</a></h2><p>Clicking a definition (or <code>/eskills edit &lt;id&gt;</code>) opens its editor page. Every submenu shares <code>gui/editor_page_gui.yml</code>; the title follows the current submenu and fields render into the content grid:</p><table tabindex="0"><thead><tr><th>Slot key</th><th>Type</th><th>Default position</th><th>Meaning</th></tr></thead><tbody><tr><td><code>preview</code></td><td><code>preview</code></td><td>4</td><td>Definition preview: builds a display item from the draft&#39;s <code>icon_material</code> / <code>display_name</code></td></tr><tr><td><code>field_entry</code></td><td><code>field_entry</code></td><td>content rows 2-4</td><td>Field entries; interactions listed below</td></tr><tr><td><code>back_parent</code></td><td><code>back_parent</code></td><td>0</td><td>Back to the parent menu</td></tr><tr><td><code>back_home</code></td><td><code>back_home</code></td><td>1</td><td>Back to the editor home menu</td></tr><tr><td><code>close</code></td><td><code>close</code></td><td>8</td><td>Close the editor</td></tr><tr><td><code>confirm</code></td><td><code>confirm</code></td><td>36</td><td>&quot;Add&quot;: append one item to the current list</td></tr><tr><td><code>page_prev</code></td><td><code>page_prev</code></td><td>38</td><td>Previous page</td></tr><tr><td><code>page_info</code></td><td><code>page_info</code></td><td>40</td><td>Page number and entry count</td></tr><tr><td><code>page_next</code></td><td><code>page_next</code></td><td>42</td><td>Next page</td></tr><tr><td><code>border</code></td><td><code>filler</code></td><td>remaining slots</td><td>Decorative filler, not interactive</td></tr></tbody></table><p>Deep skill fields get their own submenus: cast condition, skill variables, skill script (with cast/hit/miss/fail action phases), upgrade settings (including upgrade economy), and resource cost entries. Field interactions (exactly what the in-game hints say):</p><table tabindex="0"><thead><tr><th>Field shape</th><th>Interaction</th></tr></thead><tbody><tr><td>Toggle</td><td>Left-click switches on/off, right-click resets</td></tr><tr><td>Enum</td><td>Left-click cycles to the next value, right-click resets</td></tr><tr><td>Number</td><td>Left-click prompts for a value in chat, right-click resets</td></tr><tr><td>Text</td><td>Left-click prompts for text in chat, right-click resets</td></tr><tr><td>Submenu</td><td>Left-click enters</td></tr><tr><td>List</td><td>Left-click views; sequence lists: left-click adds a row, Shift+left-click edits an entry, right-click removes the last row, Shift+right-click clears</td></tr><tr><td>Map</td><td>Left-click edits an entry (type <code>key=value</code> in chat), right-click resets the whole node</td></tr></tbody></table><p>Type <code>cancel</code> in chat to abort an input prompt; a malformed map entry is rejected with a <code>key=value</code> hint</p><h2 id="validation-and-saving" tabindex="-1">Validation and saving <a class="header-anchor" href="#validation-and-saving" aria-label="Permalink to “Validation and saving”">​</a></h2><ul><li>Every field edit is validated immediately: the YAML must parse, the definition id cannot be empty or change (<code>id_changed</code>), and the content must be readable by the matching parser (the skill parser for skills, the resource parser for local resources). Skills with <code>enabled: false</code> skip the parse check, so you can disable one first and edit it at your own pace.</li><li>On success the chat says &quot;Successfully modified %item%&quot; with an experience-orb sound; on failure it reports the reason with a villager-no sound and the <strong>edit does not take effect</strong>. Parse failures (<code>definition_parse_failed</code>) log the details to console.</li><li>Edits accumulate in the editing session and the plugin writes them to disk at its flush points: before any <code>/eskills reload</code> and before the plugin shuts down, pending edits are flushed first. Run <code>/eskills reload</code> to persist and apply changes right away.</li><li>Creating and deleting reload the module immediately, so those take effect at once.</li><li>If an external program changed the file underneath you, the write is rejected by a revision check (a conflict is reported) instead of silently overwriting it; an oversized definition document is also rejected</li></ul><h2 id="edit-backups" tabindex="-1">edit-backups <a class="header-anchor" href="#edit-backups" aria-label="Permalink to “edit-backups”">​</a></h2><p>Before every write to disk, the previous contents of the file are backed up to:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiSkills/edit-backups/&lt;millisecond timestamp&gt;/&lt;file name&gt;.yml</span></span></code></pre></div><p>Deletion works the same way: the file is copied into <code>edit-backups</code> before it is removed from its directory, which is why the confirmation screen says the action cannot be undone but a backup is written to edit-backups first. If you delete the wrong definition, copy the file back from the backup directory. Backups go into per-timestamp folders and never overwrite each other; clean them up periodically</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to “Related pages”">​</a></h2><ul><li><a href="./commands.html">Commands and permissions</a>: the <code>/eskills edit</code> entry point and its permissions</li><li><a href="./definitions.html">Skill definitions</a>: field meanings and values for skills and local resources</li><li><a href="./triggers.html">Triggers</a>: <code>trigger_type</code>, conflicting skills, and trigger binding fields</li><li><a href="./script.html">Native scripting</a> / <a href="./scripts.html">JS scripting</a>: the <code>script</code> action pipeline and script skills</li></ul>`,28)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};